/*
 * pc_overlay_sections.h - where each overlay's variables live in the PC
 * executable (table generated by tools/pc_port/gen_overlay_sections.py).
 */
#ifndef PC_OVERLAY_SECTIONS_H
#define PC_OVERLAY_SECTIONS_H

typedef struct PcOverlayData {
    char *begin;   /* first byte of the overlay's .data + .bss */
    char *end;     /* one past the last byte */
} PcOverlayData;

/* Indexed by overlay ID; only built with Clang (PPL_OVERLAY_RESET). */
extern const PcOverlayData gPcOverlayData[];

/* Every other game variable (main program + game-facing Nitro layer):
 * restored by a soft reset. */
extern const PcOverlayData gPcMainData;

#endif
